  EXPECT_EQ(info_input_1->GetDataType(), ge::DT_INT8);
  EXPECT_EQ(info_input_1->GetOriginFormat(), ge::FORMAT_NCDHW);
  EXPECT_EQ(info_input_1->GetStorageFormat(), ge::FORMAT_RESERVED);
